8	const UpdateBookingSchema = z.object({
9	  artist_id: z.string().uuid().optional(),
10	  service_id: z.string().uuid().nullable().optional(),
11	  location_id: z.string().uuid().nullable().optional(),
12	  scheduled_at: z.string().datetime().optional(),
13	  duration_min: z.number().int().min(15).max(480).optional(),
14	  price_cents: z.number().int().min(0).optional(),
15	  deposit_cents: z.number().int().min(0).optional(),
