24	export async function GET(_request: NextRequest, { params }: Params) {
25	  const authUser = await getAuthenticatedUser()
26	  if (!authUser) {
27	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
28	  }
29	
30	  const { success } = await authedRatelimit.limit(authUser.user.id)
31	  if (!success) {
32	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
33	  }
34	
35	  const { id } = await params
36	  if (!z.string().uuid().safeParse(id).success) {
37	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
38	  }
39	
40	  try {
41	    const supabase = await createClient()
42	    const { data, error } = await supabase
43	      .from('bookings')
44	      .select(
45	        `
46	        *,
47	        client:clients(id, first_name, last_name, email, phone, total_sessions, total_spent_cents, tags, notes),
48	        artist:artists(id, display_name, avatar_url, sort_order),
49	        service:services(id, name, duration_min, base_price_cents, deposit_cents, color),
50	        location:locations(id, name, address, city),
51	        photos:booking_photos(id, kind, caption, taken_at, storage_path)
52	      `
53	      )
54	      .eq('id', id)
55	      .eq('studio_id', authUser.studioId)
56	      .single()
57	
58	    if (error || !data) {
59	      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
60	    }
61	
62	    return NextResponse.json({ data })
63	  } catch (err) {
64	    logger.error({ err, bookingId: id }, 'booking GET unexpected error')
65	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
66	  }
67	}
