69	export async function PATCH(request: NextRequest, { params }: Params) {
70	  const authUser = await getAuthenticatedUser()
71	  if (!authUser) {
72	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
73	  }
74	
75	  const { success } = await authedRatelimit.limit(authUser.user.id)
76	  if (!success) {
77	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
78	  }
79	
80	  const { id } = await params
81	  if (!z.string().uuid().safeParse(id).success) {
82	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
83	  }
84	
85	  let body: unknown
86	  try {
87	    body = await request.json()
88	  } catch {
89	    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
90	  }
91	
92	  const parsed = UpdateBookingSchema.safeParse(body)
93	  if (!parsed.success) {
94	    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
95	  }
96	
97	  if (Object.keys(parsed.data).length === 0) {
98	    return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
99	  }
100	
101	  try {
102	    const supabase = await createClient()
103	    // Strip undefined values — required for exactOptionalPropertyTypes + Supabase update
104	    const updates = Object.fromEntries(
105	      Object.entries(parsed.data).filter(([, v]) => v !== undefined)
106	    )
107	    const { data, error } = await supabase
108	      .from('bookings')
109	      .update(updates)
110	      .eq('id', id)
111	      .eq('studio_id', authUser.studioId)
112	      .select('id, scheduled_at, end_at, duration_min, status, price_cents, notes, updated_at')
113	      .single()
114	
115	    if (error) {
116	      if (error.code === '23P01') {
117	        return NextResponse.json(
118	          { error: 'That time slot is already booked for this artist' },
119	          { status: 409 }
120	        )
121	      }
122	      if (error.code === 'PGRST116') {
123	        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
124	      }
125	      logger.error({ err: error, bookingId: id }, 'booking PATCH failed')
126	      return NextResponse.json({ error: 'Failed to update booking' }, { status: 500 })
127	    }
128	
129	    return NextResponse.json({ data })
130	  } catch (err) {
131	    logger.error({ err, bookingId: id }, 'booking PATCH unexpected error')
132	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
133	  }
134	}
