136	export async function DELETE(_request: NextRequest, { params }: Params) {
137	  const authUser = await getAuthenticatedUser()
138	  if (!authUser) {
139	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
140	  }
141	
142	  const { success } = await authedRatelimit.limit(authUser.user.id)
143	  if (!success) {
144	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
145	  }
146	
147	  const { id } = await params
148	  if (!z.string().uuid().safeParse(id).success) {
149	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
150	  }
151	
152	  try {
153	    const supabase = await createClient()
154	    const { error } = await supabase
155	      .from('bookings')
156	      .update({ status: 'cancelled', cancelled_at: new Date().toISOString() })
157	      .eq('id', id)
158	      .eq('studio_id', authUser.studioId)
159	
160	    if (error) {
161	      if (error.code === 'PGRST116') {
162	        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
163	      }
164	      logger.error({ err: error, bookingId: id }, 'booking DELETE failed')
165	      return NextResponse.json({ error: 'Failed to cancel booking' }, { status: 500 })
166	    }
167	
168	    return new NextResponse(null, { status: 204 })
169	  } catch (err) {
170	    logger.error({ err, bookingId: id }, 'booking DELETE unexpected error')
171	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
172	  }
173	}
